 public class WaveView:Control {
  public int Duration,Position,Start,End,ViewStart,ViewEnd;float[] peaks;public event Action<int> Seek;
  public WaveView(){DoubleBuffered=true;BackColor=Color.FromArgb(24,34,48);ForeColor=Color.FromArgb(78,194,190);Cursor=Cursors.Hand;Height=125;}
  public void LoadWave(string path,int duration){byte[] b=File.ReadAllBytes(path);int channels=Data.U16(b,22),samples=(b.Length-44)/(channels*2);Duration=duration;peaks=new float[2400];
   for(int bin=0;bin<peaks.Length;bin++){int a=(int)((long)bin*samples/peaks.Length),z=(int)((long)(bin+1)*samples/peaks.Length);int max=0;
    for(int i=a;i<z;i++)for(int c=0;c<channels;c++)max=Math.Max(max,Math.Abs((int)BitConverter.ToInt16(b,44+(i*channels+c)*2)));peaks[bin]=max/32768f;}ViewStart=0;ViewEnd=duration;Invalidate();}
  public void Reset(){peaks=null;Duration=Position=ViewStart=ViewEnd=0;Invalidate();}
  public void FocusCue(bool zoom){if(Duration==0)return;ViewStart=zoom?Math.Max(0,Start-4000):0;ViewEnd=zoom?Math.Min(Duration,End+4000):Duration;if(ViewEnd-ViewStart<1000)ViewEnd=Math.Min(Duration,ViewStart+1000);Invalidate();}
  protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(Duration>0&&Seek!=null)Seek(ViewStart+(int)((long)Math.Max(0,e.X-12)*Math.Max(1,ViewEnd-ViewStart)/Math.Max(1,Width-24)));}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;int w=Width-24,h=Height-40;g.SmoothingMode=SmoothingMode.None;int range=Math.Max(1,ViewEnd-ViewStart);
   Func<int,int> x=t=>12+(int)((long)(t-ViewStart)*w/range);if(Duration>0){using(var b=new SolidBrush(Color.FromArgb(55,51,149,245)))g.FillRectangle(b,x(Start),6,Math.Max(1,x(End)-x(Start)),h+8);
    using(var pen=new Pen(ForeColor)){if(peaks!=null)for(int i=0;i<w;i++){int t=ViewStart+(int)((long)i*range/Math.Max(1,w)),bin=Math.Min(peaks.Length-1,Math.Max(0,(int)((long)t*peaks.Length/Math.Max(1,Duration))));int v=(int)(peaks[bin]*h/2);g.DrawLine(pen,i+12,8+h/2-v,i+12,8+h/2+v);}}
    using(var p=new Pen(Color.FromArgb(107,183,255),2)){g.DrawLine(p,x(Start),5,x(Start),h+20);g.DrawLine(p,x(End),5,x(End),h+20);}
    if(Position>=ViewStart&&Position<=ViewEnd)using(var p=new Pen(Color.FromArgb(255,206,90),2))g.DrawLine(p,x(Position),2,x(Position),h+20);
    using(var b=new SolidBrush(Color.Gainsboro)){g.DrawString(Data.Time(ViewStart),Font,b,10,Height-24);g.DrawString(Data.Time(ViewEnd),Font,b,Math.Max(12,Width-95),Height-24);}
   }else TextRenderer.DrawText(g,"음성을 불러오면 파형이 표시됩니다",Font,ClientRectangle,Color.Silver,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);
  }
 }
 public class PreviewBox:Control {
  Bitmap image;public string Caption="";public PreviewBox(){DoubleBuffered=true;Height=110;BackColor=Color.FromArgb(44,49,58);}
  public void SetText(string text){Caption=text;if(image!=null)image.Dispose();try{image=Data.Preview(text);}catch{image=null;}Invalidate();}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var r=ClientRectangle;using(var b=new LinearGradientBrush(r,Color.FromArgb(74,82,94),Color.FromArgb(24,31,42),90f))e.Graphics.FillRectangle(b,r);
   if(image!=null){float scale=Math.Min((Width-12)/640f,(Height-12)/64f);int w=(int)(640*scale),h=(int)(64*scale);e.Graphics.InterpolationMode=InterpolationMode.NearestNeighbor;e.Graphics.DrawImage(image,(Width-w)/2,(Height-h)/2,w,h);}}
 }
