  bool HasDraft(){return current!=null&&(current.Start!=(int)Math.Round(start.Value*1000)||current.End!=(int)Math.Round((start.Value+duration.Value)*1000)||current.Text!=text.Text.Replace("\r\n","\n"));}
  bool ConfirmDraft(){if(!HasDraft())return true;var result=MessageBox.Show(this,"입력한 자막을 적용할까요?\r\n[예] 이 자막에 적용  [아니요] 입력 취소", "적용하지 않은 입력",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(result==DialogResult.Cancel)return false;if(result==DialogResult.Yes)return ApplyDraft();return true;}
  bool ConfirmLeave(){if(!ConfirmDraft())return false;if(!projectDirty)return true;var r=MessageBox.Show(this,"수정 내용을 작업 파일에 저장할까요?", "작업 저장",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(r==DialogResult.Cancel)return false;if(r==DialogResult.Yes)return SaveProject();return true;}
  void SetBusy(bool b,string title){busy=b;if(!b)workingSession=null;cancel.Enabled=b;status.Text=title;progress.Value=0;UpdateEnabled();}
  void UpdateEnabled(){bool available=!busy&&session!=null;open.Enabled=load.Enabled=!busy;save.Enabled=export.Enabled=available;undoButton.Enabled=available&&undo.Count>0;redoButton.Enabled=available&&redo.Count>0;grid.Enabled=search.Enabled=clips.Enabled=onlyChanged.Enabled=!busy;text.Enabled=start.Enabled=duration.Enabled=apply.Enabled=restore.Enabled=available&&current!=null;
   foreach(var b in new[]{loadVoice,play,segment,stop,previous,next})b.Enabled=available&&current!=null;setStart.Enabled=setEnd.Enabled=available&&current!=null&&player.Opened&&loadedClip==current.Clip;}
  void Progress(Session s){s.Progress=(label,p)=>{if(IsDisposed)return;BeginInvoke((Action)(()=>{status.Text=label;progress.Value=Math.Max(0,Math.Min(1000,(int)(p*1000)));}));};progress.Maximum=1000;}
  async void OpenClick(object sender,EventArgs e){if(!ConfirmLeave())return;using(var d=new OpenFileDialog{Filter="한글패치 CHD|*.chd",Title="v1.4/v1.5 한글패치 CHD 열기"})if(d.ShowDialog(this)==DialogResult.OK)await OpenChd(d.FileName);}
  async Task OpenChd(string path){if(busy)return;player.Close();looping=false;SetBusy(true,"CHD를 읽는 중입니다…");var nextSession=new Session();workingSession=nextSession;Progress(nextSession);
   try{await Task.Run(()=>nextSession.Open(path));if(session!=null)session.Dispose();session=nextSession;nextSession=null;projectPath=null;projectDirty=false;undo.Clear();redo.Clear();LoadSessionView();status.Text="불러오기 완료 · 자막을 선택하고 [선택 자막 듣기]를 누르세요.";}
   catch(Exception ex){if(nextSession!=null)nextSession.Dispose();Error(ex);status.Text="불러오지 못했습니다.";}finally{SetBusy(false,status.Text);}}
  public void UseSession(Session s){session=s;LoadSessionView();UpdateEnabled();}
  void LoadSessionView(){changing=true;loadedClip=-1;current=null;wave.Reset();clips.Items.Clear();clips.Items.Add("전체 장면 / 음성");foreach(var id in session.Project.Cues.Select(x=>x.Clip).Distinct().OrderBy(x=>x))clips.Items.Add(new ClipItem{Id=id,Text=session.Label(id)});clips.SelectedIndex=0;search.Clear();onlyChanged.Checked=false;discLabel.Text="디스크 "+session.Spec.Disc+" · "+session.Project.Cues.Count.ToString("N0")+"개 자막";changing=false;RefreshGrid();}
  class ClipItem {public int Id;public string Text;public override string ToString(){return Text;}}
  void RefreshGrid(){if(changing||session==null)return;string selected=current==null?null:current.Id,needle=search.Text.Trim();var filter=clips.SelectedItem as ClipItem;
   visible=session.Project.Cues.Where(c=>(filter==null||c.Clip==filter.Id)&&(!onlyChanged.Checked||c.Changed)&&(needle.Length==0||c.Text.IndexOf(needle,StringComparison.CurrentCultureIgnoreCase)>=0||c.Id.IndexOf(needle,StringComparison.OrdinalIgnoreCase)>=0||session.Label(c.Clip).IndexOf(needle,StringComparison.OrdinalIgnoreCase)>=0)).OrderBy(c=>c.Clip).ThenBy(c=>c.Start).ToList();
   changing=true;grid.RowCount=visible.Count;grid.ClearSelection();int index=selected==null?-1:visible.FindIndex(x=>x.Id==selected);if(index<0&&visible.Count>0)index=0;if(index>=0){grid.CurrentCell=grid.Rows[index].Cells[4];grid.Rows[index].Selected=true;}changing=false;grid.Invalidate();stats.Text=visible.Count.ToString("N0")+"개 표시 / 전체 "+session.Project.Cues.Count.ToString("N0")+"개 · 수정 "+session.Project.Cues.Count(c=>c.Changed)+"개";SelectRow();}
  void SelectRow(){if(changing||session==null)return;int i=grid.CurrentCell==null?-1:grid.CurrentCell.RowIndex;if(i<0||i>=visible.Count){current=null;UpdateEnabled();return;}var nextCue=visible[i];if(current!=null&&nextCue.Id!=current.Id&&HasDraft()){
    if(!ConfirmDraft()){changing=true;int old=visible.FindIndex(x=>x.Id==current.Id);if(old>=0)grid.CurrentCell=grid.Rows[old].Cells[4];changing=false;return;}}
   if(current!=null&&current.Id!=nextCue.Id){looping=false;if(player.Opened&&player.Playing)player.Pause();}
   if(player.Opened&&loadedClip!=nextCue.Clip){player.Close();loadedClip=-1;wave.Reset();position.Text="00:00.000 / 00:00.000";}
   current=nextCue;LoadDetails();}
  void LoadDetails(){if(current==null)return;changing=true;cueLabel.Text=current.Id;start.Value=current.Start/1000m;duration.Value=(current.End-current.Start)/1000m;text.Text=current.Text.Replace("\n","\r\n");changing=false;
   audioLabel.Text=session.Label(current.Clip)+" · 음성 길이 "+Data.Time(session.Clips[current.Clip].Duration);wave.Start=current.Start;wave.End=current.End;wave.FocusCue(zoom.Checked);DetailsChanged(this,EventArgs.Empty);UpdateEnabled();}
  void DetailsChanged(object sender,EventArgs e){if(changing||current==null)return;wave.Start=(int)Math.Round(start.Value*1000);wave.End=(int)Math.Round((start.Value+duration.Value)*1000);wave.Invalidate();string s=text.Text.Replace("\r\n","\n");preview.SetText(s);
   try{Data.CheckText(s);validation.ForeColor=Color.FromArgb(48,111,82);validation.Text="종료 "+Data.Time(wave.End)+" · 다른 자막은 이동하지 않습니다.";if(wave.End>session.Clips[current.Clip].Duration){validation.ForeColor=Color.DarkOrange;validation.Text="음성 끝을 넘는 시간입니다. 게임에서는 음성 종료 시 자막이 지워집니다.";}}
   catch(Exception ex){validation.ForeColor=Color.Firebrick;validation.Text=ex.Message;}}
  bool ApplyDraft(){if(current==null)return false;var before=current.Copy();current.Start=(int)Math.Round(start.Value*1000);current.End=(int)Math.Round((start.Value+duration.Value)*1000);current.Text=text.Text.Replace("\r\n","\n");
   try{session.Validate(session.Project,true);if(before.Start!=current.Start||before.End!=current.End||before.Text!=current.Text){undo.Push(new EditAction{Before=before,After=current.Copy()});redo.Clear();projectDirty=true;}RefreshGrid();UpdateEnabled();status.Text="선택한 자막에만 적용했습니다. 다른 자막은 변경하지 않았습니다.";return true;}
   catch(Exception ex){Copy(before,current);Error(ex);return false;}}
  static void Copy(Cue from,Cue to){to.Start=from.Start;to.End=from.End;to.Text=from.Text;}
  void ApplyClick(object s,EventArgs e){ApplyDraft();}
  void RestoreClick(object s,EventArgs e){if(current==null)return;start.Value=current.OriginalStart/1000m;duration.Value=(current.OriginalEnd-current.OriginalStart)/1000m;text.Text=current.OriginalText.Replace("\n","\r\n");ApplyDraft();}
  void Undo(bool forward){if(busy||session==null)return;var source=forward?redo:undo;var dest=forward?undo:redo;if(source.Count==0)return;var action=source.Pop();var target=session.Project.Cues.First(x=>x.Id==action.Before.Id);Copy(forward?action.After:action.Before,target);dest.Push(action);projectDirty=true;current=target;RefreshGrid();UpdateEnabled();status.Text=forward?"다시 실행했습니다.":"실행을 취소했습니다.";}
  void MoveRow(int by){if(grid.CurrentCell==null||visible.Count==0)return;int row=Math.Max(0,Math.Min(visible.Count-1,grid.CurrentCell.RowIndex+by));grid.CurrentCell=grid.Rows[row].Cells[4];}
  bool SaveProject(){if(session==null||!ConfirmDraft())return false;string path=projectPath;using(var d=new SaveFileDialog{Filter="자막 작업 파일|*.kazeproj",FileName=path==null?"바람의 리글렛 디스크"+session.Spec.Disc+" 자막.kazeproj":Path.GetFileName(path),InitialDirectory=path==null?Path.GetDirectoryName(session.Project.Source):Path.GetDirectoryName(path)}){
    if(d.ShowDialog(this)!=DialogResult.OK)return false;path=d.FileName;}try{Data.WriteJson(path,session.Project);projectPath=path;projectDirty=false;status.Text="작업 파일 저장 완료 · "+Path.GetFileName(path);return true;}catch(Exception ex){Error(ex);return false;}}
  void SaveClick(object s,EventArgs e){SaveProject();}
  async void LoadClick(object s,EventArgs e){if(!ConfirmLeave())return;using(var d=new OpenFileDialog{Filter="자막 작업 파일|*.kazeproj"}){if(d.ShowDialog(this)!=DialogResult.OK)return;try{var p=Data.ReadJson<Project>(d.FileName);if(!File.Exists(p.Source)){using(var rom=new OpenFileDialog{Filter="원본으로 사용한 한글패치 CHD|*.chd",Title="이 작업의 CHD를 지정하세요"}){if(rom.ShowDialog(this)!=DialogResult.OK)return;p.Source=rom.FileName;}}
     await OpenChd(p.Source);if(session==null)return;session.ApplyProject(p);projectPath=d.FileName;projectDirty=false;undo.Clear();redo.Clear();LoadSessionView();status.Text="저장했던 수정 내용을 불러왔습니다.";}catch(Exception ex){Error(ex);}}}
  async void ExportClick(object s,EventArgs e){if(session==null||!ConfirmDraft())return;using(var d=new SaveFileDialog{Filter="편집한 게임 CHD|*.chd",FileName=Path.GetFileNameWithoutExtension(session.Project.Source)+" [자막수정].chd",InitialDirectory=Path.GetDirectoryName(session.Project.Source),OverwritePrompt=false}){
    if(d.ShowDialog(this)!=DialogResult.OK)return;SetBusy(true,"새 CHD를 저장합니다…");workingSession=session;player.Close();loadedClip=-1;looping=false;session.Cancel=false;
    try{await Task.Run(()=>session.SaveChd(d.FileName));status.Text="새 CHD 저장 완료 · 원본은 그대로 보존했습니다.";MessageBox.Show(this,"새 CHD를 저장하고 무결성을 확인했습니다.\r\n\r\n"+d.FileName+"\r\n\r\nFlycast는 완전히 종료 후 새 CHD로 부팅하세요. 이전 세이브스테이트를 사용하지 마세요.","저장 완료",MessageBoxButtons.OK,MessageBoxIcon.Information);}
    catch(Exception ex){Error(ex);status.Text="CHD 저장이 완료되지 않았습니다.";}finally{SetBusy(false,status.Text);}}}
  async Task<bool> LoadAudio(){if(busy||session==null||current==null)return false;if(loadedClip==current.Clip&&player.Opened)return true;int fid=current.Clip;player.Close();looping=false;SetBusy(true,"음성을 불러옵니다…");workingSession=session;session.Cancel=false;
   try{string wav=await Task.Run(()=>session.Audio(fid));if(session.Cancel)throw new OperationCanceledException();player.Open(wav);wave.LoadWave(wav,session.Clips[fid].Duration);loadedClip=fid;wave.Start=current.Start;wave.End=current.End;wave.FocusCue(zoom.Checked);player.Seek(Math.Min(current.Start,session.Clips[fid].Duration));UpdatePosition();status.Text="음성을 불러왔습니다. 파형을 누르면 해당 위치로 이동합니다.";return true;}
   catch(Exception ex){loadedClip=-1;Error(ex);return false;}finally{SetBusy(false,status.Text);}}
  async Task PlayPause(){if(busy)return;if(player.Opened&&player.Playing){player.Pause();looping=false;return;}if(!await LoadAudio())return;int p=player.Position,limit=session.Clips[loadedClip].Duration;if(p>=limit-50)p=0;looping=false;player.Play(p,limit);}
  async Task PlaySegment(){if(!await LoadAudio())return;loopStart=Math.Max(0,(int)(start.Value*1000)-650);playEnd=Math.Min(session.Clips[loadedClip].Duration,(int)((start.Value+duration.Value)*1000)+650);looping=repeat.Checked;player.Play(loopStart,playEnd);}
  void UpdatePosition(){if(!player.Opened)return;int p=player.Position;wave.Position=p;wave.Invalidate();position.Text=Data.Time(p)+" / "+Data.Time(session.Clips[loadedClip].Duration);
   if(player.Playing){var c=session.Project.Cues.Where(x=>x.Clip==loadedClip&&x.Start<=p&&p<x.End).OrderBy(x=>x.Start).LastOrDefault();string caption=c==null?"":c.Text;if(current!=null&&current.Clip==loadedClip&&wave.Start<=p&&p<wave.End)caption=text.Text.Replace("\r\n","\n");if(preview.Caption!=caption)preview.SetText(caption);}}
  void Tick(object s,EventArgs e){if(busy||session==null||!player.Opened)return;try{UpdatePosition();if(looping&&repeat.Checked&&!player.Playing&&player.Position>=playEnd-120)player.Play(loopStart,playEnd);}catch{looping=false;}}
  async void EditorKeys(object s,KeyEventArgs e){if(busy)return;if(e.Control&&e.KeyCode==System.Windows.Forms.Keys.S){e.SuppressKeyPress=true;SaveProject();}else if(e.Control&&e.KeyCode==System.Windows.Forms.Keys.Z&&!text.ContainsFocus&&!search.ContainsFocus){e.SuppressKeyPress=true;Undo(false);}else if(e.Control&&e.KeyCode==System.Windows.Forms.Keys.Y&&!text.ContainsFocus&&!search.ContainsFocus){e.SuppressKeyPress=true;Undo(true);}else if(e.KeyCode==System.Windows.Forms.Keys.Space&&!text.ContainsFocus&&!search.ContainsFocus&&!start.ContainsFocus&&!duration.ContainsFocus){e.SuppressKeyPress=true;await PlayPause();}}
  void OnEditorClosing(object s,FormClosingEventArgs e){if(busy){e.Cancel=true;MessageBox.Show(this,"CHD 작업 중입니다. [취소]를 누르고 작업이 끝난 뒤 닫아 주세요.","작업 중");return;}if(!ConfirmLeave()){e.Cancel=true;return;}timer.Stop();player.Dispose();if(session!=null){session.Dispose();session=null;}}
  public object SmokeTest(string screenshot){smokeMode=true;ShowInTaskbar=false;StartPosition=FormStartPosition.Manual;Location=new Point(-30000,-30000);Show();Application.DoEvents();PerformLayout();foreach(Control c in Controls)c.PerformLayout();RefreshGrid();if(visible.Count<1000)throw new Exception("UI population failed");
   var target=visible.First(x=>x.Clip>=79&&x.Start>1000&&x.End-x.Start>1500);int row=visible.IndexOf(target);grid.CurrentCell=grid.Rows[row].Cells[4];SelectRow();var initial=target.Copy();start.Value=(target.Start+20)/1000m;duration.Value=(target.End-target.Start-20)/1000m;
   if(!ApplyDraft())throw new Exception("UI timing apply failed");if(target.Start!=initial.Start+20)throw new Exception("UI did not apply edit");Undo(false);if(target.Start!=initial.Start)throw new Exception("UI undo failed");Undo(true);if(target.Start!=initial.Start+20)throw new Exception("UI redo failed");Undo(false);projectDirty=false;
   string path=session.Audio(target.Clip);player.Open(path);loadedClip=target.Clip;player.Seek(target.Start);UpdateEnabled();if(!setStart.Enabled)throw new Exception("Position marking unavailable after loading audio");
   int other=visible.FindIndex(x=>x.Clip!=target.Clip);grid.CurrentCell=grid.Rows[other].Cells[4];SelectRow();if(player.Opened||setStart.Enabled)throw new Exception("Old voice remained attached to a different clip");
   SetBusy(true,"취소 동작 확인");workingSession=session;cancel.PerformClick();if(!session.Cancel)throw new Exception("Cancel did not reach active session");session.Cancel=false;SetBusy(false,"");
   grid.CurrentCell=grid.Rows[row].Cells[4];SelectRow();player.Open(path);loadedClip=target.Clip;player.Seek(target.Start);wave.LoadWave(path,session.Clips[target.Clip].Duration);wave.Start=target.Start;wave.End=target.End;wave.Position=target.Start;position.Text=Data.Time(target.Start)+" / "+Data.Time(session.Clips[target.Clip].Duration);wave.FocusCue(true);preview.SetText(target.Text);UpdateEnabled();status.Text="검증 화면 · CHD에서 불러온 자막과 실제 음성 파형";
   Application.DoEvents();using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(screenshot,System.Drawing.Imaging.ImageFormat.Png);}Hide();player.Close();return new{Rows=visible.Count,Apply=true,Undo=true,Redo=true,OldVoiceClearedOnClipChange=true,CancelDispatch=true,NoPhysicalInput=true};
  }
 }
 public static class Program {
  [STAThread]public static int Main(string[] args){try{Console.SetOut(new StreamWriter(Console.OpenStandardOutput(),new UTF8Encoding(false)){AutoFlush=true});Console.SetError(new StreamWriter(Console.OpenStandardError(),new UTF8Encoding(false)){AutoFlush=true});}catch{}try{Data.Init();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
   if(args.Length==2&&args[0]=="--screenshot"){using(var f=new MainForm()){f.EmptyScreenshot(args[1]);}return 0;}if(args.Length>0&&args[0].StartsWith("--")){return Cli(args);}Application.Run(new MainForm());return 0;
  }catch(Exception ex){if(args.Length>0&&args[0].StartsWith("--")){Console.Error.WriteLine(ex.ToString());return 1;}MessageBox.Show(ex.Message,"자막 편집기",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
  static int Cli(string[] a){using(var s=new Session()){s.Progress=(stage,p)=>Console.WriteLine(stage+" "+(int)(p*100)+"%");
   if(a[0]=="--player-test"){Data.WriteJson(a[2],Player.Test(a[1]));return 0;}
   if(a[0]=="--inspect"){s.Open(a[1]);Data.WriteJson(a[2],s.Project);string chars;List<string> ids;byte[] packed=s.Pack(s.Project,out chars,out ids),body=s.BuildExe(s.Project,false);if(!packed.SequenceEqual(s.Blob)||!body.SequenceEqual(Data.Slice(s.Exe,0,body.Length)))throw new Exception("No-edit binary roundtrip failed");Data.WriteJson(a[2]+".report.json",new{Disc=s.Spec.Disc,Cues=s.Project.Cues.Count,Glyphs=chars.Length,ExactRoundtrip=true,Warnings=s.Warnings(s.Project).Count});return 0;}
   if(a[0]=="--export"||a[0]=="--audio"||a[0]=="--ui-test"){var p=Data.ReadJson<Project>(a[1]);s.Open(p.Source);s.ApplyProject(p);
    if(a[0]=="--export")s.SaveChd(a[2]);else if(a[0]=="--audio")File.Copy(s.Audio(int.Parse(a[2])),a[3],true);else {using(var f=new MainForm()){f.UseSession(s);var result=f.SmokeTest(a[2]);Data.WriteJson(a[2]+".report.json",result);}}return 0;}
   throw new UserError("지원하지 않는 명령입니다.");}}
 }
}


